@page "/board"
@using sv_25eff0e404d54834a9128a389dc64a51.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Kanban Board</h2>

@if (isLoading)
{
    <p class="board-loading">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="tasks" />

    <div class="board-search">
        <input type="text" placeholder="Search tasks by title…"
               @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="kanban-board">
        @foreach (var col in columns)
        {
            var colIndex = Array.IndexOf(columns, col);
            <KanbanColumn Title="@col"
                          Status="@col"
                          Tasks="GetFilteredTasks(col)"
                          CanMoveLeft="colIndex > 0"
                          CanMoveRight="colIndex < columns.Length - 1"
                          LeftStatus="@(colIndex > 0 ? columns[colIndex - 1] : null)"
                          RightStatus="@(colIndex < columns.Length - 1 ? columns[colIndex + 1] : null)"
                          OnMoveTask="HandleMoveTask"
                          OnAddTask="HandleAddTask" />
        }
    </div>
}

@code {
    private readonly string[] columns = ["To Do", "In Progress", "Done"];
    private List<TaskItem> tasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t =>
                t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }

        return filtered.ToList();
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var task = tasks.First(t => t.Id == move.TaskId);
            var index = tasks.IndexOf(task);
            tasks[index] = task with { Status = move.NewStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(TaskItem draft)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(
                draft.Title, draft.Assignee, draft.Priority, draft.DueDate);
            tasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

.board-loading {
    text-align: center;
    padding: 2rem;
    color: #6b7280;
}

.board-error {
    text-align: center;
    padding: 2rem;
    color: #dc2626;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    cursor: pointer;
}

/* Stats bar */
.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f3f4f6;
    border-radius: 8px;
    margin-bottom: 1rem;
}

.stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: 700;
}

.stat-label {
    font-size: 0.8rem;
    color: #6b7280;
}

.stat-overdue .stat-value {
    color: #dc2626;
}

/* Search */
.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
}

/* Kanban layout */
.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    min-height: 300px;
}

.column-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e5e7eb;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.task-count {
    color: #9ca3af;
    font-weight: 400;
}

.column-body {
    padding: 0.5rem;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.column-footer {
    padding: 0.5rem;
    border-top: 1px solid #e5e7eb;
}

/* Task card */
.task-card {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem;
    font-size: 0.85rem;
    color: #6b7280;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #fecaca;
    color: #991b1b;
}

.priority-medium {
    background: #fef08a;
    color: #854d0e;
}

.priority-low {
    background: #bbf7d0;
    color: #166534;
}

.task-due-date {
    font-size: 0.8rem;
    color: #6b7280;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    border: 1px solid #d1d5db;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.btn-move:hover:not(:disabled) {
    background: #f3f4f6;
}

.btn-move:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Add task */
.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #d1d5db;
    background: transparent;
    border-radius: 6px;
    cursor: pointer;
    color: #6b7280;
    font-size: 0.9rem;
}

.btn-add-task:hover {
    background: #f3f4f6;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.form-field label {
    display: block;
    font-size: 0.8rem;
    margin-bottom: 0.15rem;
    color: #374151;
}

.form-field input,
.form-field select {
    width: 100%;
    padding: 0.35rem 0.5rem;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-error {
    color: #dc2626;
    font-size: 0.8rem;
    margin: 0;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save,
.btn-cancel {
    padding: 0.35rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-save {
    background: #2563eb;
    color: #fff;
    border-color: #2563eb;
}

.btn-save:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-cancel {
    background: #fff;
}

.btn-cancel:hover:not(:disabled) {
    background: #f3f4f6;
}

