@page "/board"
@using sv_25eff0e404d54834a9128a389dc64a51.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Kanban Board</h2>

@if (isLoading)
{
    <p class="board-loading">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="tasks" />

    <div class="board-search">
        <input type="text" placeholder="Search tasks by title…"
               @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="kanban-board">
        @foreach (var col in columns)
        {
            var colIndex = Array.IndexOf(columns, col);
            <KanbanColumn Title="@col"
                          Status="@col"
                          Tasks="GetFilteredTasks(col)"
                          CanMoveLeft="colIndex > 0"
                          CanMoveRight="colIndex < columns.Length - 1"
                          LeftStatus="@(colIndex > 0 ? columns[colIndex - 1] : null)"
                          RightStatus="@(colIndex < columns.Length - 1 ? columns[colIndex + 1] : null)"
                          OnMoveTask="HandleMoveTask"
                          OnAddTask="HandleAddTask" />
        }
    </div>
}

@code {
    private readonly string[] columns = ["To Do", "In Progress", "Done"];
    private List<TaskItem> tasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t =>
                t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }

        return filtered.ToList();
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var task = tasks.First(t => t.Id == move.TaskId);
            var index = tasks.IndexOf(task);
            tasks[index] = task with { Status = move.NewStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(TaskItem draft)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(
                draft.Title, draft.Assignee, draft.Priority, draft.DueDate);
            tasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

