.board-loading {
    text-align: center;
    padding: 2rem;
    color: #6b7280;
}

.board-error {
    text-align: center;
    padding: 2rem;
    color: #dc2626;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    cursor: pointer;
}

/* Stats bar */
.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f3f4f6;
    border-radius: 8px;
    margin-bottom: 1rem;
}

.stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: 700;
}

.stat-label {
    font-size: 0.8rem;
    color: #6b7280;
}

.stat-overdue .stat-value {
    color: #dc2626;
}

/* Search */
.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
}

/* Kanban layout */
.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    min-height: 300px;
}

.column-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e5e7eb;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.task-count {
    color: #9ca3af;
    font-weight: 400;
}

.column-body {
    padding: 0.5rem;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.column-footer {
    padding: 0.5rem;
    border-top: 1px solid #e5e7eb;
}

