.task-card {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem;
    font-size: 0.85rem;
    color: #6b7280;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #fecaca;
    color: #991b1b;
}

.priority-medium {
    background: #fef08a;
    color: #854d0e;
}

.priority-low {
    background: #bbf7d0;
    color: #166534;
}

.task-due-date {
    font-size: 0.8rem;
    color: #6b7280;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
